/**
 * The single owner record for the workspace browser.
 *
 * Why this file exists: with several agents sharing one headed Edge, "who
 * started it" and "did closing the window actually end it" were unanswerable.
 * This record makes both a lookup instead of a guess.
 *
 * Identity is the DevTools browser UUID, not the pid: a pid can be recycled,
 * but the UUID is regenerated by every Chromium launch. So `edge.json` is
 * trusted only while `/json/version` on the recorded port still reports the
 * recorded uuid.
 */
import fs from 'node:fs';
import { readText, writeTextAtomic } from './paths.js';

/** @typedef {{pid:number, port:number, uuid:string, wsUrl:string, startedAt:string, headed:boolean, profileDir:string, spawnedBy:Record<string,unknown>, logFile:string|null}} OwnerRecord */

/**
 * Read the owner record.
 * @param {string} file
 * @returns {OwnerRecord|null} null when absent or unreadable.
 */
export function readOwner(file) {
  try {
    const parsed = JSON.parse(readText(file));
    if (!parsed || typeof parsed !== 'object' || !parsed.uuid) return null;
    return parsed;
  } catch {
    return null;
  }
}

/**
 * Persist the owner record.
 * @param {string} file
 * @param {OwnerRecord} record
 */
export function writeOwner(file, record) {
  writeTextAtomic(file, JSON.stringify(record, null, 2) + '\n');
}

/**
 * Delete the owner record, if any.
 * @param {string} file
 */
export function clearOwner(file) {
  try { fs.unlinkSync(file); } catch { /* already gone */ }
}

/**
 * Whether a pid is alive. Used only as a secondary hint: pid liveness alone
 * never proves the process is *our* browser.
 * @param {number} pid
 * @returns {boolean}
 */
export function pidAlive(pid) {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try { process.kill(pid, 0); return true; }
  catch (e) { return e && e.code === 'EPERM'; }
}
